#!/usr/bin/env bash
source "$(dirname "$0")/common.sh"
heading 'Paso 34 — curar nuevos dominios en Silver'
[[ -s "$ROOT/state/$DEMO_RUN_ID/bronze_nuevos_ok.txt" ]] || { echo 'SCRIPT 34: 0 — falta 33'; exit 1; }
Q(){ bq --project_id="$PROJECT_ID" --location="$REGION" query --use_legacy_sql=false --maximum_bytes_billed=31457280 "$1"; }
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.benchmark_competidores\` T USING (SELECT JSON_VALUE(payload_json,'$.benchmark_id') benchmark_id, JSON_VALUE(payload_json,'$.competitor_id') competitor_id, JSON_VALUE(payload_json,'$.sku_id') sku_id, JSON_VALUE(payload_json,'$.store_id') store_id, SAFE_CAST(JSON_VALUE(payload_json,'$.observed_at') AS TIMESTAMP) observed_at, SAFE_CAST(JSON_VALUE(payload_json,'$.competitor_price') AS NUMERIC) competitor_price, JSON_VALUE(payload_json,'$.availability') availability, IF(is_valid,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.benchmark_competidores_raw\` WHERE batch_id='$DEMO_RUN_ID') S ON T.benchmark_id=S.benchmark_id WHEN NOT MATCHED THEN INSERT ROW"
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.eventos_locales\` T USING (SELECT JSON_VALUE(payload_json,'$.local_event_id') local_event_id, JSON_VALUE(payload_json,'$.store_id') store_id, JSON_VALUE(payload_json,'$.event_type') event_type, SAFE_CAST(JSON_VALUE(payload_json,'$.start_at') AS TIMESTAMP) start_at, SAFE_CAST(JSON_VALUE(payload_json,'$.end_at') AS TIMESTAMP) end_at, SAFE_CAST(JSON_VALUE(payload_json,'$.impact_score') AS FLOAT64) impact_score, IF(is_valid,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.eventos_locales_raw\` WHERE batch_id='$DEMO_RUN_ID') S ON T.local_event_id=S.local_event_id WHEN NOT MATCHED THEN INSERT ROW"
Q "MERGE \`$PROJECT_ID.$SILVER_DATASET.redes_sociales\` T USING (SELECT JSON_VALUE(payload_json,'$.post_id') post_id, JSON_VALUE(payload_json,'$.platform') platform, SAFE_CAST(JSON_VALUE(payload_json,'$.published_at') AS TIMESTAMP) published_at, JSON_VALUE(payload_json,'$.sku_id') sku_id, SAFE_CAST(JSON_VALUE(payload_json,'$.sentiment_score') AS FLOAT64) sentiment_score, SAFE_CAST(JSON_VALUE(payload_json,'$.engagement_count') AS INT64) engagement_count, JSON_VALUE(payload_json,'$.text_hash') text_hash, IF(is_valid,'VALID','INVALID') quality_status FROM \`$PROJECT_ID.$BRONZE_DATASET.redes_sociales_raw\` WHERE batch_id='$DEMO_RUN_ID') S ON T.post_id=S.post_id WHEN NOT MATCHED THEN INSERT ROW"
printf 'Silver nuevos curado\n' > "$ROOT/state/$DEMO_RUN_ID/silver_nuevos_ok.txt"
echo 'SCRIPT 34: 1 — Silver curado'
